            public bool? IncludeQaIssues { get; set; }
            /// <summary>Languages to be contained in response.                To add multiple languages, repeat this param (eg. ?languages=en&amp;languages=de)</summary>
#if NETSTANDARD2_1_OR_GREATER || NETCOREAPP3_1_OR_GREATER
#nullable enable
            [QueryParameter("languages")]
            public string[]? Languages { get; set; }
#nullable restore
#else
            [QueryParameter("languages")]
            public string[] Languages { get; set; }
#endif
            /// <summary>Zero-based page index (0..N)</summary>
            [QueryParameter("page")]
            public int? Page { get; set; }
            /// <summary>String to search in key name or translation text</summary>
#if NETSTANDARD2_1_OR_GREATER || NETCOREAPP3_1_OR_GREATER
#nullable enable
            [QueryParameter("search")]
            public string? Search { get; set; }
#nullable restore
#else
            [QueryParameter("search")]
            public string Search { get; set; }
#endif
            /// <summary>The size of the page to be returned</summary>
