            public int? Size { get; set; }
            /// <summary>Sorting criteria in the format: property,(asc|desc). Default sort order is ascending. Multiple sort criteria are supported.</summary>
#if NETSTANDARD2_1_OR_GREATER || NETCOREAPP3_1_OR_GREATER
#nullable enable
            [QueryParameter("sort")]
